INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, -416.5, 190805, "2025/01/31 12:00:00", 1, 0.0, 1, 3.414, 2, "2030/01/01 14:59:59", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 62, 1000001, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, -416.5, 190805, "2025/01/31 12:00:00", 1, 0.0, 1, 3.099, 2, "2030/01/01 14:59:59", "ミッションをクリアして、\n報酬をゲットしましょう！", 62, 1000002, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, -416.5, 190805, "2025/01/31 12:00:00", 1, 0.0, 1, 2.801, 2, "2030/01/01 14:59:59", "受け取ることができる\n報酬があるようです\n確認してみてください", 63, 1000003, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, -416.5, 190805, "2025/01/31 12:00:00", 1, 0.0, 2, 0.0, 2, "2030/01/01 14:59:59", "報酬がもらえますよ！\nチェックしてみてください", 63, 1000004, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5, -363.0, 190805, "2025/01/31 12:00:00", 1, 0.0, 2, 2.12, 1, "2030/01/01 14:59:59", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 64, 1000005, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6, -363.0, 190805, "2025/01/31 12:00:00", 1, 0.0, 1, 1.68, 2, "2030/01/01 14:59:59", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 64, 1000006, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7, -363.0, 190805, "2025/01/31 12:00:00", 1, 0.0, 2, 2.33, 1, "2030/01/01 14:59:59", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 64, 1000007, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 133701, "2025/01/31 12:00:00", 10201, -6.0, 3, 5.18, 7, "2030/01/01 14:59:59", "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 61, 1020101, "ラビリスタ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 133901, "2025/01/31 12:00:00", 10201, -2.0, 1, 8.77, 2, "2030/01/01 14:59:59", "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 61, 1020102, "クリスティーナ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, -285.0, 133801, "2025/01/31 12:00:00", 10201, 0.0, 6, 15.5, 1, "2030/01/01 14:59:59", "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 61, 1020103, "ネネカ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 134301, "2025/02/28 12:00:00", 10202, 0.0, 2, 9.061, 5, "2030/01/01 14:59:59", "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 61, 1020201, "ランファ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 134401, "2025/02/28 12:00:00", 10202, 0.0, 1, 7.699, 2, "2030/01/01 14:59:59", "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 61, 1020202, "チカ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 134601, "2025/03/31 12:00:00", 10203, 0.0, 1, 8.595, 2, "2030/01/01 14:59:59", "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 61, 1020301, "アオイ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 134501, "2025/03/31 12:00:00", 10203, 0.0, 1, 7.758, 2, "2030/01/01 14:59:59", "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 61, 1020302, "クローチェ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 132302, "2025/04/30 12:00:00", 10204, 0.0, 2, 7.0, 6, "2030/01/01 14:59:59", "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 61, 1020401, "ルイズマリー");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 132402, "2025/04/30 12:00:00", 10204, 0.0, 1, 7.904, 2, "2030/01/01 14:59:59", "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 61, 1020402, "イロハ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, -285.0, 132502, "2025/04/30 12:00:00", 10204, 0.0, 4, 8.487, 2, "2030/01/01 14:59:59", "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 61, 1020403, "ソノ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 134901, "2025/05/31 12:00:00", 10205, 0.0, 1, 8.763, 2, "2030/01/01 14:59:59", "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 61, 1020502, "カノン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 134801, "2025/05/31 12:00:00", 10205, 0.0, 1, 6.417, 3, "2030/01/01 14:59:59", "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 61, 1020503, "ツムギ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 135001, "2025/06/30 12:00:00", 10206, 0.0, 3, 10.335, 7, "2030/01/01 14:59:59", "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 61, 1020601, "エリス");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 135101, "2025/06/30 12:00:00", 10206, 0.0, 2, 6.281, 4, "2030/01/01 14:59:59", "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 61, 1020602, "シェフィ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, -285.0, 135201, "2025/06/30 12:00:00", 10206, 0.0, 1, 12.244, 2, "2030/01/01 14:59:59", "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 61, 1020603, "プレシア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 135301, "2025/07/31 12:00:00", 10207, 0.0, 2, 6.339, 8, "2030/01/01 14:59:59", "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 61, 1020701, "クリア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 135401, "2025/07/31 12:00:00", 10207, 0.0, 7, 8.184, 9, "2030/01/01 14:59:59", "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 61, 1020702, "アネモネ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 129101, "2025/08/31 12:00:00", 10208, 0.0, 9, 3.906, 2, "2030/01/01 14:59:59", "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 61, 1020801, "アイラ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 129201, "2025/08/31 12:00:00", 10208, 0.0, 1, 14.465, 2, "2030/01/01 14:59:59", "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 61, 1020802, "シナツ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, -285.0, 100101, "2025/08/31 12:00:00", 10208, 0.0, 4, 8.662, 3, "2030/01/01 14:59:59", "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 61, 1020803, "ヒヨリ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (401, -285.0, 100301, "2025/08/31 12:00:00", 10208, 0.0, 1, 10.915, 3, "2030/01/01 14:59:59", "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 61, 1020804, "レイ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 135802, "2025/09/30 12:00:00", 10209, 0.0, 1, 6.042, 7, "2030/01/01 14:59:59", "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 61, 1020901, "ユキノ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 135903, "2025/09/30 12:00:00", 10209, 0.0, 4, 9.402, 1, "2030/01/01 14:59:59", "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 61, 1020902, "サツキ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, -285.0, 136902, "2025/09/30 12:00:00", 10209, 0.0, 8, 8.16, 1, "2030/01/01 14:59:59", "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 61, 1020903, "ルルィ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 137401, "2025/10/31 12:00:00", 10210, 0.0, 3, 5.0, 2, "2030/01/01 14:59:59", "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 61, 1021001, "カスミ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 136001, "2025/10/31 12:00:00", 10210, 0.0, 4, 8.12, 1, "2030/01/01 14:59:59", "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 61, 1021002, "アラクネ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, -285.0, 136202, "2025/10/31 12:00:00", 10210, 0.0, 4, 6.386, 2, "2030/01/01 14:59:59", "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 61, 1021003, "ナーナ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 136402, "2025/11/30 12:00:00", 10211, 0.0, 3, 7.438, 4, "2030/01/01 14:59:59", "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 61, 1021101, "ユイ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 136302, "2025/11/30 12:00:00", 10211, 0.0, 1, 8.35, 5, "2030/01/01 14:59:59", "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 61, 1021102, "ミソラ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 136501, "2025/12/31 12:00:00", 10212, 0.0, 1, 5.0, 2, "2030/01/01 14:59:59", "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 61, 1021201, "シズル");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 137902, "2025/12/31 12:00:00", 10212, 0.0, 1, 5.25, 2, "2030/01/01 14:59:59", "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 61, 1021202, "リノ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, -285.0, 106801, "2025/12/31 12:00:00", 10212, 0.0, 1, 7.5, 2, "2030/01/01 14:59:59", "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 61, 1021203, "ラビリスタ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 126501, "2026/01/31 12:00:00", 10213, 0.0, 1, 8.204, 2, "2030/01/01 14:59:59", "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 61, 1021301, "ライラエル");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 129701, "2026/01/31 12:00:00", 10213, 0.0, 1, 7.176, 2, "2030/01/01 14:59:59", "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 61, 1021302, "ネフィ＝ネラ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, -285.0, 133101, "2026/01/31 12:00:00", 10213, 0.0, 1, 8.602, 5, "2030/01/01 14:59:59", "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 61, 1021303, "ヴァイオレット");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (102, -285.0, 138101, "2026/02/06 12:00:00", 10213, 0.0, 1, 10.14, 3, "2030/01/01 14:59:59", "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 61, 1021304, "ライラエル");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (202, -285.0, 138201, "2026/02/06 12:00:00", 10213, 0.0, 1, 10.152, 7, "2030/01/01 14:59:59", "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 61, 1021305, "ネフィ＝ネラ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (302, -285.0, 138001, "2026/02/06 12:00:00", 10213, 0.0, 4, 9.688, 3, "2030/01/01 14:59:59", "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 61, 1021306, "ヴァイオレット");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (401, -285.0, 138301, "2026/02/12 12:00:00", 10213, 0.0, 2, 5.928, 1, "2030/01/01 14:59:59", "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 61, 1021307, "ペコリーヌ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 138702, "2026/02/28 12:00:00", 10214, 0.0, 4, 9.19, 2, "2030/01/01 14:59:59", "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 61, 1021401, "ワカナ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 138802, "2026/02/28 12:00:00", 10214, 0.0, 1, 8.724, 3, "2030/01/01 14:59:59", "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 61, 1021402, "シオリ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 138902, "2026/03/31 12:00:00", 10215, 0.0, 4, 7.758, 1, "2030/01/01 14:59:59", "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 61, 1021501, "グレイス");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 139002, "2026/03/31 12:00:00", 10215, 0.0, 6, 6.375, 4, "2030/01/01 14:59:59", "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 61, 1021502, "キョウカ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, -285.0, 136902, "2026/03/31 12:00:00", 10215, 0.0, 6, 6.173, 1, "2030/01/01 14:59:59", "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 61, 1021503, "ルルィ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 139202, "2026/04/30 12:00:00", 10216, 0.0, 6, 4.202, 2, "2030/01/01 14:59:59", "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 61, 1021601, "ミホ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 139302, "2026/04/30 12:00:00", 10216, 0.0, 6, 2.842, 1, "2030/01/01 14:59:59", "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 61, 1021602, "マホ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, -285.0, 139402, "2026/04/30 12:00:00", 10216, 0.0, 4, 4.598, 1, "2030/01/01 14:59:59", "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 61, 1021603, "エリカ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 125802, "2026/05/31 12:00:00", 10217, 0.0, 4, 6.533, 3, "2030/01/01 14:59:59", "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 61, 1021701, "リリ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, -285.0, 126102, "2026/05/31 12:00:00", 10217, 0.0, 3, 5.0, 3, "2030/01/01 14:59:59", "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 61, 1021702, "プレシア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 126002, "2026/05/31 12:00:00", 10217, 0.0, 3, 5.214, 4, "2030/01/01 14:59:59", "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 61, 1021703, "クリア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (102, -285.0, 139501, "2026/05/31 12:00:00", 10217, 0.0, 1, 8.781, 3, "2030/01/01 14:59:59", "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 61, 1021704, "リリ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (202, -285.0, 139601, "2026/05/31 12:00:00", 10217, 0.0, 2, 6.529, 1, "2030/01/01 14:59:59", "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 61, 1021705, "クリア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (302, -285.0, 139701, "2026/05/31 12:00:00", 10217, 0.0, 3, 3.195, 2, "2030/01/01 14:59:59", "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 61, 1021706, "プレシア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 139902, "2026/06/30 12:00:00", 10218, 0.0, 2, 12.43, 3, "2030/01/01 14:59:59", "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 61, 1021801, "ルイズマリー");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 140001, "2026/06/30 12:00:00", 10218, 0.0, 2, 6.35, 3, "2030/01/01 14:59:59", "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 61, 1021802, "クレジッタ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, -285.0, 140102, "2026/07/31 12:00:00", 10219, 0.0, 1, 10.23, 5, "2030/01/01 14:59:59", "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 61, 1021901, "フブキ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, -285.0, 140201, "2026/07/31 12:00:00", 10219, 0.0, 1, 5.584, 2, "2030/01/01 14:59:59", "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 61, 1021902, "ヴァンピィ");
